import{_ as a,o as s,c as t,a3 as r}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"Establishing a Customer Support (Free Consultation and Q&A) Department","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"建立售后\\\\(义诊答疑\\\\)部门","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer","scope":"page"}},"headers":[],"relativePath":"src/page-AnG8YkyaK2VGhXykemIDer.md","filePath":"logistics/src/page-AnG8YkyaK2VGhXykemIDer.md","lastUpdated":null}'),o={name:"src/page-AnG8YkyaK2VGhXykemIDer.md"};function n(p,e,i,c,l,u){return s(),t("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="建立售后-义诊答疑-部门" aria-hidden="true"></span><h1 id="establishing-a-customer-support-free-consultation-and-q-a-department" tabindex="-1">Establishing a Customer Support (Free Consultation and Q&amp;A) Department <a class="header-anchor" href="#establishing-a-customer-support-free-consultation-and-q-a-department" aria-label="Permalink to &quot;Establishing a Customer Support (Free Consultation and Q&amp;A) Department&quot;">​</a></h1><blockquote><p>Source page ID: <code>AnG8YkyaK2VGhXykemIDer</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Due to the summary of issues in the <a href="./page-bjB7jF3g7E11H2AlmcZ3JQ">results-publication process</a>, we decided to establish a customer-support department.</p><p>Collect the names of people involved in after-sales support.</p><p><span class="mark-grey">#言: After-sales support and Q&amp;A should be able to trace root causes and resolve most possible issues. In practice, this requires using reports to backtrack problems with reasonable accuracy, a clear understanding of every module&#39;s functions, and a basic understanding of automatic balancing/adaptive devices. It also requires some spare time to handle questions and learn the necessary knowledge.</span></p><p>Establish a relevant group chat.</p><p><span class="mark-grey">The group number should not be posted here; relevant personnel should manually review and invite members.</span></p><p><span id="source-block-K1QLU97ywaQqerFz7hD7qK"></span></p><span class="logistics-source-anchor" id="售后-答疑报名处" aria-hidden="true"></span><h2 id="customer-support-q-a-sign-up" tabindex="-1">Customer Support / Q&amp;A Sign-up <a class="header-anchor" href="#customer-support-q-a-sign-up" aria-label="Permalink to &quot;Customer Support / Q&amp;A Sign-up&quot;">​</a></h2><p>jmy</p><p>东弓与葛冰之</p><p>NH（D-15191）</p><p><span id="source-block-n2NeK8zgbi9dRIjBQcTKpl"></span></p><span class="logistics-source-anchor" id="售后-答疑名单" aria-hidden="true"></span><h2 id="customer-support-q-a-roster" tabindex="-1">Customer Support / Q&amp;A Roster <a class="header-anchor" href="#customer-support-q-a-roster" aria-label="Permalink to &quot;Customer Support / Q&amp;A Roster&quot;">​</a></h2><p><span id="source-block-9fU6RZ0Clraa1KB7ThLxkv"></span></p><span class="logistics-source-anchor" id="兜底答疑名单" aria-hidden="true"></span><h2 id="backup-q-a-roster" tabindex="-1">Backup Q&amp;A Roster <a class="header-anchor" href="#backup-q-a-roster" aria-label="Permalink to &quot;Backup Q&amp;A Roster&quot;">​</a></h2></div>',1)])])}const h=a(o,[["render",n]]);export{m as __pageData,h as default};
